// Draft generated by expl-bot-report (--tests) from run eb-261106-1157. Not run against the app yet.
// Shared by the specs in this folder. The login steps come from the login page snapshot, not from an
// executed action: the user logged in by hand during the exploratory run.
import { expect, type Page } from '@playwright/test';

export const BASE_URL = 'https://www.saucedemo.com/';

// Credentials are never stored in this repo. The login page lists the public demo accounts and the shared
// password; pass them through the environment, for example:
//   SAUCE_USERNAME=standard_user SAUCE_PASSWORD=<password shown on the login page> npx playwright test tests/expl-bot
export async function login(page: Page): Promise<void> {
  const username = process.env.SAUCE_USERNAME;
  const password = process.env.SAUCE_PASSWORD;
  if (!username || !password) {
    throw new Error('Set SAUCE_USERNAME and SAUCE_PASSWORD (see the comment in tests/expl-bot/helpers.ts)');
  }
  await page.goto(BASE_URL);
  await page.getByRole('textbox', { name: 'Username' }).fill(username);
  await page.getByRole('textbox', { name: 'Password' }).fill(password);
  await page.getByRole('button', { name: 'Login' }).click();
  await expect(page).toHaveURL(/\/inventory\.html$/);
}

export const addButton = (page: Page, slug: string) => page.locator(`[data-test="add-to-cart-${slug}"]`);
export const removeButton = (page: Page, slug: string) => page.locator(`[data-test="remove-${slug}"]`);
export const cartBadge = (page: Page) => page.locator('.shopping_cart_badge');
export const cartLink = (page: Page) => page.locator('a.shopping_cart_link');
export const sortSelect = (page: Page) => page.locator('[data-test="product-sort-container"]');
export const itemNames = (page: Page) => page.locator('[data-test="inventory-item-name"]');
export const itemPrices = (page: Page) => page.locator('[data-test="inventory-item-price"]');
